(function () {
  var langs = Object.keys(I18N), nav = (navigator.language || "fr").slice(0, 2);
  var lang = null; try { lang = localStorage.getItem("lang"); } catch (e) {}
  if (!I18N[lang]) lang = I18N[nav] ? nav : "fr";
  window.LANG = lang;
  function applique(l) {
    var d = I18N[l];
    document.documentElement.lang = l;
    document.documentElement.dir = l === "ar" ? "rtl" : "ltr";
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      var k = el.dataset.i18n; if (d[k] != null) el.textContent = d[k];
    });
    window.LANG = l;
    var sel = document.getElementById("lang"); if (sel) sel.value = l;
    document.dispatchEvent(new CustomEvent("langchange", { detail: l }));
  }
  window.setLang = function (l) { if (!I18N[l]) return; try { localStorage.setItem("lang", l); } catch (e) {} applique(l); };
  window.langOptions = function () { return langs.map(function (l) { return '<option value="' + l + '"' + (l === lang ? " selected" : "") + ">" + I18N[l]._n + "</option>"; }).join(""); };
  document.addEventListener("DOMContentLoaded", function () { applique(lang); });
})();
